const e={id:"formeToit",libelle:"Forme du toit",champs:{forme:{type:"object",additionalProperties:!1,required:["indices","valeur"],properties:{indices:{$ref:"#/$defs/indices"},valeur:{type:"string",enum:["plat","appentis","deux-pans","croupes","pavillon","demi-croupe","mansart","asymetrique","deux-pans-decales","toit-en-m","papillon","gambrel","coyau","shed","berceau","carene","conique","polygonal","fleche","dome","imperiale","indetermine"]}}},profil:{type:"object",additionalProperties:!1,required:["indices","valeur"],properties:{indices:{$ref:"#/$defs/indices"},valeur:{type:"string",enum:["droit","brise","courbe","indetermine"]}}},faitage:{type:"object",additionalProperties:!1,required:["indices","sens"],properties:{indices:{$ref:"#/$defs/indices"},sens:{type:"string",enum:["perpendiculaire-rue","parallele-rue","sans-faitage","indetermine"]}}},bouts:{type:"object",additionalProperties:!1,required:["indices","gauche","droite"],properties:{indices:{$ref:"#/$defs/indices"},gauche:{$ref:"#/$defs/bout"},droite:{$ref:"#/$defs/bout"}}}},definitions:{bout:{type:"string",enum:["pignon","croupe","demi-croupe","brisis","sans-objet","indetermine"]}},consignes:[{rang:1,texte:"- `forme` : la forme du catalogue qui décrit le corps principal."},{rang:2,texte:"- `profil` : la coupe en travers d'un pan — `droit` (une seule pente), `brise` (brisis et terrasson, Mansart ou gambrel), `courbe` (berceau, carène, dôme)."},{rang:3,texte:"- `faitage.sens` : le sens du faîtage par rapport à la rue vue sur la photo ; `sans-faitage` pour un toit plat, un pavillon ou une forme à sommet unique."},{rang:4,texte:"- `bouts.gauche`, `bouts.droite` : ce qui ferme chaque bout du faîtage, vu depuis la rue (gauche et droite de la photo) ; `sans-objet` quand il n'y a pas de faîtage."}],vocabulaire:[{section:"Surfaces",rang:1,texte:`- **Versant** (ou pan) : surface inclinée plane qui reçoit et conduit l'eau.
- **Croupe** : pan triangulaire ou trapézoïdal qui ferme le bout d'un toit, à la place d'un pignon.
- **Demi-croupe** (croupette) : croupe qui ne descend pas jusqu'à l'égout ; un petit pignon dessous, la croupe au-dessus.
- **Brisis** : partie basse, très raide (60° à 80°), d'un toit brisé ; porte souvent les lucarnes.
- **Terrasson** : partie haute, peu pentue (15° à 30°), d'un toit brisé.
- **Toiture-terrasse** : toit plat (moins de 3° à 5°), souvent bordé d'un acrotère.
- **Renvers** : pan à contre-pente qui renvoie l'eau vers une noue ou un chéneau.`},{section:"Lignes",rang:2,texte:`- **Faîtage** : ligne horizontale la plus haute, où se rejoignent deux versants opposés.
- **Égout** : bord bas d'un versant, où l'eau quitte le toit vers la gouttière.
- **Arêtier** : angle saillant entre deux pans (entre un long pan et une croupe).
- **Noue** : angle rentrant entre deux pans (jonction d'un bâtiment en L, d'une aile).
- **Ligne de bris** : ligne horizontale entre le brisis et le terrasson.
- **Rive** : bord latéral incliné d'un versant, le long d'un mur pignon.
- **Pignon** : mur triangulaire qui porte les versants au bout d'un toit à deux pans ; au sens étendu, un avant-corps à deux pans perpendiculaire au faîtage.`},{section:"Sens du faîtage",rang:3,texte:"- `parallele-rue` : le faîtage longe la façade vue de la rue ; on voit le long pan, et le toit monte vers le fond ;\n- `perpendiculaire-rue` : le faîtage va vers la rue ; on voit un pignon (ou une croupe) face à soi, et le toit descend de part et d'autre ;\n- `sans-faitage` : il n'y a pas de ligne de faîte (toit plat, pavillon, forme à sommet unique)."},{section:"Formes",rang:30,texte:"- `plat` : toit-terrasse, pente de moins de 5 %.\n- `appentis` : monopente, un seul pan, adossé à un mur ou libre.\n- `deux-pans` : deux pans et deux murs pignons aux bouts.\n- `croupes` : quatre pans, deux grands pans et deux croupes aux bouts.\n- `pavillon` : quatre pans triangulaires réunis en un point, plan presque carré.\n- `demi-croupe` : deux pans dont le haut des bouts est fermé par une courte croupe, un petit pignon dessous.\n- `mansart` : chaque face a deux pentes, terrasson en haut, brisis en bas, brisis aussi aux bouts.\n- `asymetrique` : deux pans, l'un nettement plus long et qui descend plus bas.\n- `deux-pans-decales` : deux pans aux faîtages à des hauteurs différentes, séparés par une bande verticale.\n- `toit-en-m` : deux toits à deux pans parallèles et accolés, réunis par une noue centrale.\n- `papillon` : deux pans inclinés vers l'intérieur, noue centrale.\n- `gambrel` : double pente du Mansart sur les deux longs côtés seulement, avec des murs pignons.\n- `coyau` : toit dont le bas de chaque pan s'évase et s'adoucit vers l'extérieur.\n- `shed` : appentis répétés en dents de scie.\n- `berceau` : toit en demi-cylindre ou en arc surbaissé.\n- `carene` : silhouette convexe en coque de bateau renversée.\n- `conique` : cône sur une tourelle ronde ou polygonale.\n- `polygonal` : pavillon sur un plan hexagonal ou octogonal.\n- `fleche` : pyramide ou cône très élancé.\n- `dome` : hémisphère ou calotte sur une base ronde ou polygonale.\n- `imperiale` : galbe en S, d'abord bombé puis effilé."}],lectures:[{rang:1,titre:"Lire les pignons d'abord",texte:"Le haut d'une façade est ce qui dit le mieux la forme du toit. Avant de choisir `forme`, `profil` et `bouts`, regardez, pour chaque façade photographiée, la **silhouette de son haut** sur la photo, puis sur le rendu (le contour noir la montre) :\n\n- **triangle** (deux rampes qui montent jusqu'à un sommet, mur plein dessous) : un mur pignon ; le faîtage est perpendiculaire à cette façade. Un bout en `pignon`, et un `deux-pans` (ou un `croupes` si l'autre bout se ferme en croupe) ;\n- **trapèze** (rampes qui s'arrêtent sur une ligne plate au sommet, ou toit qui ne se voit qu'en pente) : une croupe ou une demi-croupe, pas un pignon ; sous une demi-croupe, un petit triangle de mur ;\n- **une seule rampe** : un appentis, ou le long pan d'un `deux-pans` vu de côté (le faîtage est alors parallèle à la façade) ;\n- **ligne droite, avec ou sans acrotère** : un toit plat, ou le long pan vu de face sous l'égout ;\n- **marches** : un pignon à redents ;\n- **plusieurs sommets** côte à côte : plusieurs corps, ou un toit en M ;\n- **triangle plus bas que le faîtage voisin** : une lucarne ou un petit corps (confusion 1 ci-dessous), pas le pignon du corps principal.\n\nReportez ce que vous lisez dans chaque entrée de `facades` : `silhouette` (le mot ci-dessus) et `bout` (ce que cette façade ferme : `pignon`, `croupe`, `demi-croupe`, `brisis`, ou `sans-objet` pour un long pan). Plan en tire le sens du faîtage et les bouts du toit. Ensuite, comparez cette silhouette à celle du rendu, façade par façade : le nombre de sommets, le côté et la hauteur où la rampe s'arrête, la présence d'un triangle de mur, le débord de l'égout. Chaque différence vue sur les images va dans `ecarts` : `sujet` `bouts` quand un pignon est pris pour une croupe ou l'inverse, `forme` ou `corps` quand la silhouette d'ensemble ne correspond pas, et dites ce que dit le rendu (`modele`) et ce que montre la photo (`observe`). Ces écarts sont souvent les plus faciles à voir : ne les passez pas sous silence parce que le reste concorde. Votre `forme` et vos `bouts` se déduisent des pignons lus ; si les silhouettes des façades se contredisent, ou si une seule est vue et ne tranche pas, répondez `indetermine` plutôt que de deviner."}],grille:[{rang:1,texte:`- **plat** : pas de pente visible depuis la rue ; sur la carte LiDAR, une hauteur uniforme, souvent un liseré plus haut sur le pourtour (l'acrotère).
- **appentis** : une rampe d'un mur à l'autre ; le haut s'appuie sur un mur.
- **deux-pans** : une arête ; la hauteur reste constante le long du faîtage jusqu'aux murs de bout, qui sont des pignons.
- **croupes** : une arête raccourcie ; la hauteur baisse vers les deux bouts.
- **pavillon** : un sommet et quatre arêtiers.
- **demi-croupe** : aux bouts, le toit ne descend que sur le haut, puis un petit pignon vertical dessous.
- **mansart** : sur la photo, des fenêtres verticales dans une pente très raide le long de tous les murs ; sur la carte, une bande étroite et raide le long de tous les murs, un dessus doux ou presque plat.
- **gambrel** : la même bande raide, sur les deux longs côtés seulement ; les murs de bout montent sur toute la hauteur.
- **toit-en-m** : deux arêtes parallèles et un creux au milieu ; **papillon** : un creux au milieu sans arêtes, plus haut sur les deux murs.
- **berceau**, **carene**, **dome** : un dessus bombé, sans arête vive.`}],confusions:[{rang:2,texte:"**Mansart ou toit plat sur murs hauts.** Des fenêtres verticales dans une pente raide, une bande raide de moins de 1,5 m le long des murs, des bosses régulières dans cette bande : c'est un Mansart."},{rang:3,texte:"**Demi-croupe ou croupe.** Cherchez le petit pignon vertical sous la croupe ; s'il n'est pas visible sur une photo, répondez `indetermine` plutôt que de choisir."},{rang:5,texte:"**Pavillon ou croupes.** Un toit à quatre pans dont le faîtage fait moins de 1 m sur un plan presque carré est un pavillon."},{rang:6,texte:"**Toit en M, papillon ou deux corps.** Le toit en M a deux arêtes ; le papillon n'en a pas ; deux corps séparés ont une marche ou un mur mitoyen entre eux."},{rang:7,texte:"**Gambrel ou Mansart.** Ce sont les bouts qui tranchent : brisis aux bouts pour le Mansart, murs pignons pour le gambrel."}],rappels:[]},t={id:"lucarnes",libelle:"Lucarnes",champs:{lucarnes:{type:"object",additionalProperties:!1,required:["indices","nombre","types","pan"],properties:{indices:{$ref:"#/$defs/indices"},nombre:{$ref:"#/$defs/compte"},types:{type:"array",items:{type:"string",enum:["jacobine","capucine","chien-assis","rampante","meuniere","oeil-de-boeuf","outeau","indetermine"]}},pan:{type:"string",enum:["rue","arriere","cote","plusieurs","aucun","indetermine"]}}}},definitions:{},consignes:[{rang:5,texte:"- `lucarnes` : nombre (entier ou `indetermine`), types vus, pan qui les porte (`rue`, `arriere`, `cote`, `plusieurs`, ou `aucun` s'il n'y en a pas)."}],vocabulaire:[{section:"Ouvertures et saillies",rang:10,texte:"- **Lucarne** : ouvrage en saillie sur le versant, qui porte une fenêtre verticale.\n  - `jacobine` : deux pans, petit pignon en façade ;\n  - `capucine` : trois pans, une croupe en façade ;\n  - `chien-assis` : un pan en pente inverse du versant ;\n  - `rampante` : un pan dans le sens du versant, moins pentu ;\n  - `meuniere` (ou gerbière) : en façade, elle coupe l'égout ;\n  - `oeil-de-boeuf` : ronde ou ovale ;\n  - `outeau` : petite ouverture triangulaire de ventilation."}],lectures:[],grille:[],confusions:[{rang:1,texte:"**Grande lucarne jacobine ou avant-corps à pignon.** L'avant-corps monte jusqu'au faîtage du corps ou le touche ; la lucarne s'arrête en dessous, et son propre faîtage est plus bas que celui du corps."}],rappels:[]},s={id:"cheminees",libelle:"Cheminées",champs:{cheminees:{type:"object",additionalProperties:!1,required:["indices","nombre","souches"],properties:{indices:{$ref:"#/$defs/indices"},nombre:{$ref:"#/$defs/compte"},souches:{type:"array",items:{type:"object",additionalProperties:!1,required:["position","materiau"],properties:{position:{type:"string",enum:["faitage","pan","pignon","facade","indetermine"]},materiau:{type:"string",enum:["brique","enduit","pierre","metal","indetermine"]}}}}}}},definitions:{},consignes:[{rang:6,texte:"- `cheminees` : nombre, puis une entrée par souche vue, avec sa position et son matériau."}],vocabulaire:[{section:"Ouvertures et saillies",rang:12,texte:"- **Souche de cheminée** : maçonnerie qui sort du toit pour évacuer les fumées. Positions : `faitage` (à cheval sur le faîtage), `pan` (dans un versant), `pignon` (dans l'alignement du mur de bout), `facade` (adossée à l'extérieur d'un mur, du sol jusqu'au-dessus de l'égout). Un tubage métallique fin compte comme une cheminée en `metal`."}],lectures:[],grille:[],confusions:[{rang:4,texte:"**Cheminée, arbre ou lucarne.** Une cheminée est étroite (moins de 1,5 m de côté), souvent sur le faîtage ou un pignon ; un arbre est large, irrégulier, et déborde souvent du contour ; une lucarne est alignée sur l'égout ou dans la pente, avec un profil à pans."},{rang:8,texte:"**Cheminée, édicule ou petit corps.** Une cheminée fait moins de 1,5 m de côté (jusqu'à 2,5 m pour une souche longue) ; un édicule fait 2 m ou plus et ne se trouve que sur un toit plat ; un petit corps touche le contour et porte son propre toit en pente."}],rappels:[]},n={id:"terrasse",libelle:"Toit-terrasse",champs:{terrasse:{type:"object",additionalProperties:!1,required:["indices","presente","type","acrotere","edicules"],properties:{indices:{$ref:"#/$defs/indices"},presente:{$ref:"#/$defs/ouiNon"},type:{type:"string",enum:["inaccessible","accessible","vegetalisee","technique","sans-objet","indetermine"]},acrotere:{$ref:"#/$defs/ouiNon"},edicules:{$ref:"#/$defs/compte"}}}},definitions:{},consignes:[{rang:7,texte:"- `terrasse` : toiture-terrasse présente ou non ; son type, l'acrotère, le nombre d'édicules. `sans-objet` pour le type quand il n'y a pas de terrasse."}],vocabulaire:[{section:"Ouvertures et saillies",rang:13,texte:`- **Acrotère** : rebord maçonné en tête de mur autour d'une toiture-terrasse.
- **Édicule** : petite construction sur une terrasse (cage d'escalier, local technique), de 2 m de côté ou plus.
- **Lanterneau** : ouvrage vitré bas qui éclaire l'étage du dessous depuis une terrasse.`},{section:"Types de toiture-terrasse",rang:20,texte:"- `inaccessible` : on n'y monte que pour l'entretien (gravillons, membrane apparente) ;\n- `accessible` : une terrasse où l'on vit (dalles, carrelage, lames de bois, garde-corps) ;\n- `vegetalisee` : couverte de plantes ;\n- `technique` : porte des machines (climatisation, ventilation, panneaux solaires)."}],lectures:[],grille:[],confusions:[{rang:9,texte:"**Toiture végétalisée ou arbre.** Une toiture végétalisée a une hauteur uniforme et un contour net ; un houppier est irrégulier."}],rappels:[]},r={id:"couverture",libelle:"Couverture",champs:{couverture:{type:"object",additionalProperties:!1,required:["indices","valeur"],properties:{indices:{$ref:"#/$defs/indices"},valeur:{type:"string",enum:["tuile-plate","tuile-canal","tuile-mecanique","ardoise","ardoise-losange","zinc","bac-acier","membrane","gravillons","vegetale","indetermine"]}}}},definitions:{},consignes:[{rang:8,texte:"- `couverture` : le matériau de couverture du corps principal."}],vocabulaire:[{section:"Couvertures",rang:25,texte:"- `tuile-plate` : petites tuiles rectangulaires posées en écailles, brun rouge nuancé ;\n- `tuile-canal` : tuiles rondes demi-cylindriques en rangs alternés, ocre à rouge (toits du Sud, faible pente) ;\n- `tuile-mecanique` : grandes tuiles à emboîtement et sillons réguliers, rouge ou brun uniforme ;\n- `ardoise` : plaques fines gris bleuté, bord net, rangs bien alignés ;\n- `ardoise-losange` : grandes ardoises carrées posées sur la pointe, en losanges, gris bleuté, joints en diagonale (pas de rangs horizontaux) ;\n- `zinc` : feuilles métalliques gris clair, joints debout ;\n- `bac-acier` : tôle nervurée laquée, grandes bandes ;\n- `membrane` : revêtement d'étanchéité continu d'un toit plat ;\n- `gravillons` : lit de gravillons sur un toit plat ;\n- `vegetale` : toiture végétalisée (sedum, herbe)."}],lectures:[],grille:[],confusions:[],rappels:[]},a={id:"elements",libelle:"Éléments du toit",champs:{elements:{type:"array",items:{type:"object",additionalProperties:!1,required:["indices","element"],properties:{indices:{$ref:"#/$defs/indices"},element:{type:"string",enum:["fenetre-de-toit","chassis-eclairage","verriere","coyau","acrotere","garde-corps","lanterneau","pignon-a-redents"]}}}}},definitions:{},consignes:[{rang:9,texte:"- `elements` : les éléments qui ne se voient que sur photo ou orthophoto (fenêtres de toit, châssis, verrière, coyau, acrotère, garde-corps, lanterneau, pignon à redents), un par entrée, seulement s'ils sont vus."}],vocabulaire:[{section:"Ouvertures et saillies",rang:11,texte:"- **Châssis d'éclairage** (`chassis-eclairage`) : fenêtre plane, fixe ou à tabatière, dans le plan du versant.\n- **Fenêtre de toit** : ouvrant vitré moderne, à ras de la pente.\n- **Verrière** : grande surface vitrée en toiture."},{section:"Ouvertures et saillies",rang:14,texte:`- **Coyau** : adoucissement de la pente en bas du versant, qui relève l'égout.
- **Pignon à redents** : pignon dont le mur dépasse le toit en marches.`}],lectures:[],grille:[],confusions:[],rappels:[]},u={id:"facades",libelle:"Façades",champs:{facades:{type:"array",items:{type:"object",additionalProperties:!1,required:["indices","facade","ouvertures","details","materiau","silhouette","bout","ecart"],properties:{indices:{$ref:"#/$defs/indices"},facade:{type:"string"},ouvertures:{type:"object",additionalProperties:!1,required:["niveaux","parNiveau","manquees","enTrop"],properties:{niveaux:{$ref:"#/$defs/compte"},parNiveau:{type:"array",items:{$ref:"#/$defs/compte"}},manquees:{$ref:"#/$defs/compte"},enTrop:{$ref:"#/$defs/compte"}}},details:{type:"object",additionalProperties:!1,required:["volets","coffre","balcon","forme","vitrage","ouvrant","porte","garage","couleurVolets"],properties:{volets:{type:"string",enum:["battants","roulants","persiennes","aucun","mixte","indetermine"]},coffre:{$ref:"#/$defs/ouiNon"},balcon:{$ref:"#/$defs/ouiNon"},forme:{type:"string",enum:["rectangulaire","cintree","oeil-de-boeuf","mixte","indetermine"]},vitrage:{type:"string",enum:["plein","petits-bois","imposte-petits-bois","mixte","indetermine"]},ouvrant:{type:"string",enum:["battants","coulissant","guillotine","soufflet","fixe","mixte","indetermine"]},porte:{type:"string",enum:["pleine","vitree","semi-vitree","sans-objet","indetermine"]},garage:{type:"string",enum:["sectionnelle","basculante","battants","enroulable","sans-objet","indetermine"]},couleurVolets:{type:"string",enum:["blanc","creme","gris-clair","gris-fonce","bleu","vert","rouge","brun","bois","noir","mixte","sans-objet","indetermine"]}}},materiau:{type:"string",enum:["pierre","meuliere","beton","brique","enduit","bois","indetermine"]},silhouette:{type:"string",enum:["triangle","trapeze","rampe","ligne-droite","marches","plusieurs-sommets","indetermine"]},bout:{$ref:"#/$defs/bout"},ecart:{type:"string"}}}}},definitions:{},consignes:[{rang:10,texte:"- `facades` : une entrée par façade dont vous avez reçu une photo, désignée par son étiquette, recopiée telle quelle de la ligne « Façades à décrire » (`facade` : « sud », « nord », « est (côté 3) »…). Quand un bâtiment a plusieurs murs de même orientation, l'étiquette porte le numéro du côté du polygone : une entrée par étiquette, jamais deux murs dans la même entrée. Pour chacune :\n  - `ouvertures.niveaux` : le nombre de niveaux d'ouvertures visibles (rez-de-chaussée, étage…), `parNiveau` le nombre d'ouvertures de chaque niveau du bas vers le haut, `manquees` celles que la détection de Plan n'a pas vues et `enTrop` celles qu'elle a comptées sans qu'elles existent (d'après le nombre détecté qui vous est donné) ;\n  - `details.volets` : `battants` (deux vantaux de part et d'autre), `roulants` (un tablier qui descend d'un coffre), `persiennes` (volets ajourés repliables), `aucun`, `mixte` ; `details.coffre` : un coffre de volet roulant visible au-dessus des ouvertures ; `details.balcon` : au moins un balcon ; `details.forme` : `rectangulaire`, `cintree` (linteau en arc), `oeil-de-boeuf`, `mixte` ;\n  - `details.vitrage` : `plein` (un seul verre par vantail), `petits-bois` (la vitre divisée en petits carreaux), `imposte-petits-bois` (un verre plein surmonté d'une bande à petits carreaux) ; `details.ouvrant` : `battants` (à la française, deux vantaux ou un seul sur gonds), `coulissant` (vantaux qui glissent l'un devant l'autre, rail horizontal), `guillotine` (deux châssis l'un au-dessus de l'autre, une traverse au milieu), `soufflet` (un châssis basculant, en haut d'une baie ou seul), `fixe` (sans ouvrant) ; `details.porte` : la porte d'entrée — `pleine`, `vitree` (vitrée sur sa hauteur), `semi-vitree` (vitrée en partie haute), `sans-objet` sans porte vue ; `details.garage` : `sectionnelle` (panneaux horizontaux), `basculante` (un seul panneau lisse), `battants` (deux vantaux verticaux), `enroulable` (lames fines, coffre au-dessus), `sans-objet` sans garage ; `details.couleurVolets` : la couleur des volets ou des tabliers — `blanc`, `creme`, `gris-clair`, `gris-fonce`, `bleu`, `vert`, `rouge`, `brun`, `bois` (bois naturel ou lasuré), `noir`, `sans-objet` sans volets ;\n  - `materiau` : le parement du mur — `pierre` (pierre de taille ou moellons apparents), `meuliere` (pierre alvéolée rousse, joints marqués), `beton` (béton brut ou banché), `brique` (briques apparentes), `enduit` (enduit ou crépi peint), `bois` (bardage bois) ;\n  - `silhouette` : la ligne du haut de la façade au-dessus de l'égout, dans les mots de « Lire les pignons d'abord » — `triangle`, `trapeze`, `rampe` (une seule rampe), `ligne-droite`, `marches`, `plusieurs-sommets` ; `bout` : ce que cette façade est pour le toit, avec les mots de `bouts.gauche` — `pignon`, `croupe`, `demi-croupe` ou `brisis` quand elle ferme un bout du faîtage, `sans-objet` quand c'est un long pan (le faîtage lui est parallèle) ou qu'il n'y a pas de faîtage ; `indetermine` si le haut du mur est hors cadre ou caché ;\n  - `ecart` : en une phrase, ce qui diffère entre la photo et le rendu du modèle pour cette façade (ouvertures, hauteur, couleur), ou une chaîne vide."}],vocabulaire:[],lectures:[],grille:[],confusions:[],rappels:[{rang:1,titre:"Façades",texte:"- Comptez les ouvertures d'un niveau de gauche à droite sur la photo ; une porte compte comme une ouverture.\n- Une ouverture masquée par un arbre, une voiture ou une haie n'est ni manquée ni en trop : elle n'est pas vue.\n- Le matériau se juge sur la partie haute du mur, hors soubassement ; un enduit peint sur de la pierre est `enduit`.\n- Les détails (volets, coffre, balcon, forme, vitrage, ouvrant, couleur des volets) valent pour la majorité des ouvertures de la façade ; `mixte` quand aucune ne domine. Les petits bois se comptent sur la vitre, pas sur les volets ; des persiennes ouvertes ne disent rien du vitrage.\n- La silhouette se juge sur la ligne qui sépare le mur du ciel ; un triangle de mur au même parement que le mur est un `pignon`, un triangle couvert comme le toit une `croupe`. Les arbres et les dépendances devant le mur ne la changent pas ; hors cadre, `indetermine`. Les `bouts` et la `forme` de la maison se déduisent des `bout` des façades."}]},i={id:"murs",libelle:"Teinte et décor des murs",champs:{teinteMurs:{type:"object",additionalProperties:!1,required:["indices","valeur"],properties:{indices:{$ref:"#/$defs/indices"},valeur:{type:"string",enum:["blanc","creme","beige","ocre","rose","gris-clair","gris-fonce","brun","rouge-brique","indetermine"]}}},decorMurs:{type:"object",additionalProperties:!1,required:["indices","valeur"],properties:{indices:{$ref:"#/$defs/indices"},valeur:{type:"string",enum:["aucun","colombages","chainages-brique","bandeaux","mixte","indetermine"]}}}},definitions:{},consignes:[{rang:10.25,texte:"- `teinteMurs` : la teinte dominante du parement de la maison, sur les photos (jamais sur le rendu, qui montre le modèle) — `blanc`, `creme`, `beige`, `ocre`, `rose`, `gris-clair`, `gris-fonce`, `brun`, `rouge-brique` ; une pierre ou une brique apparente a la teinte de sa matière. `decorMurs` : ce qui se dessine sur le parement — `colombages` (pans de bois, vrais ou peints), `chainages-brique` (angles et encadrements en brique sur un autre parement), `bandeaux` (bandes horizontales entre les niveaux), `aucun`, `mixte`."}],vocabulaire:[],lectures:[],grille:[],confusions:[],rappels:[]},o={id:"transverse",libelle:"Réponse, écarts et prudence",champs:{ecarts:{type:"array",items:{type:"object",additionalProperties:!1,required:["indices","sujet","modele","observe"],properties:{indices:{$ref:"#/$defs/indices"},sujet:{type:"string",enum:["forme","profil","faitage","bouts","corps","lucarnes","cheminees","terrasse","couverture","facade","autre"]},modele:{type:"string"},observe:{type:"string"}}}},contradictions:{type:"array",items:{type:"object",additionalProperties:!1,required:["indiceLidar","observation"],properties:{indiceLidar:{type:"string"},observation:{type:"string"}}}},confiance:{type:"string",enum:["faible","moyenne","forte"]},imagesHorsSujet:{type:"array",items:{type:"integer"}}},definitions:{},consignes:[{rang:11,texte:"- `ecarts` : chaque différence entre le modèle actuel (rendu ou JSON) et ce que montrent les photos, avec ce que dit le modèle et ce que vous observez ; sujet `facade` pour un écart qui ne tient pas dans `facades[].ecart`."},{rang:12,texte:"- `contradictions` : chaque indice LiDAR chiffré que votre observation contredit (par exemple : Mansart vu sur la photo, mais aucune bande raide mesurée). Une contradiction n'est pas une erreur : elle envoie le cas en revue humaine."},{rang:13,texte:"- `confiance` : `forte` si plusieurs images concordent, `moyenne` si une seule image porte la conclusion, `faible` si les images sont mauvaises, masquées ou en désaccord."},{rang:14,texte:"- `imagesHorsSujet` : le numéro de chaque image qui ne montre pas ce bâtiment (une autre maison, un mur voisin, la rue seule) ; une liste vide quand toutes le montrent. Une image hors sujet ne porte aucun indice."}],vocabulaire:[],lectures:[],grille:[],confusions:[],rappels:[{rang:99,titre:"Règles de prudence",texte:"- Ne donnez ni hauteur, ni angle, ni dimension : ils ne font pas partie de la réponse.\n- Un élément masqué par un arbre, hors cadre ou dans l'ombre n'est pas vu : `indetermine`, ou absent de la liste.\n- Le rendu du modèle n'est jamais un indice de la réalité : citez-le seulement dans `ecarts`, et seulement s'il figure dans la liste des images. Sans rendu joint, comparez avec le JSON du modèle seulement.\n- Si les photos montrent un autre bâtiment que celui du contour, dites-le dans `ecarts` (sujet `autre`), donnez le numéro de ces images dans `imagesHorsSujet` et laissez en `indetermine` les attributs qu'aucune autre image ne montre."}]},l=[e,t,s,n,r,a,u,i,o];export{l as D};
